        "title": "Cardiac Cycle & Heartbeat",
        "body": "### The Cardiac Cycle\n\n1. **Atrial Systole:** Both atria contract simultaneously, increasing atrial pressure and forcing blood through the open atrioventricular (tricuspid and bicuspid) valves into the relaxed ventricles.\n2. **Ventricular Systole:** Ventricles contract forcefully from the base upwards. Ventricular pressure rises sharply, snapping the atrioventricular valves shut (producing the first heart sound 'lub') to prevent backflow into atria. Semi-lunar valves in the aorta and pulmonary artery burst open, pumping blood into systemic and pulmonary circuits.\n3. **Diastole:** Ventricles relax. Pressure drops below arterial pressure; semi-lunar valves snap shut (producing the second heart sound 'dub'). Blood flows passively into atria from vena cava and pulmonary veins.",
