      {
        "title": "Heart Rate Monitoring & Effects of Exercise",
        "body": "### Physical Activity & Heart Rate\n\n- During vigorous exercise, contracting muscle cells dramatically increase their rate of aerobic respiration to produce ATP for contraction.\n- Increased respiration elevates the concentration of dissolved carbon dioxide ($CO_2$) in blood plasma, forming carbonic acid and slightly lowering blood pH.\n- Chemoreceptors in the carotid arteries and aortic arch detect the pH decrease and signal the medulla oblongata in the brainstem.\n- The brain transmits impulses via the cardiac accelerator nerve to the sinoatrial node (pacemaker), increasing heart rate and stroke volume.\n- Increased cardiac output delivers oxygen and glucose to active muscles more rapidly while accelerating the clearance of carbon dioxide and lactic acid.",
        "groups": [],
        "examinerTips": [
          "Explain that exercise increases heart rate because muscles need more oxygen and glucose for respiration, and carbon dioxide must be removed."
        ],
        "commonMistakes": [
          "Saying heart rate increases to 'give muscles energy'. The heart supplies oxygen and glucose so that the muscles can **respire** to release energy."
        ],
        "recap": [
          "Explain why heart rate remains elevated for a period of time following intense sprint exercise. [3]"
        ],
        "figure": "![Heart Rate Monitoring & Effects of Exercise](/notes/biology/uq-heart-rate-monitoring-effects-of-exercise.webp)"
      }
