        "title": "Preventing & Treating CHD",
        "body": "### Management & Treatment of CHD\n\n#### Preventative Measures:\n- Regular aerobic exercise (strengthens myocardium, lowers resting blood pressure).\n- Low-saturated fat and low-salt diet (reduces LDL cholesterol atheroma deposition).\n- Cessation of smoking (eliminates nicotine vasoconstriction and carbon monoxide damage).\n\n#### Medical & Surgical Interventions:\n1. **Statins:** Prescription drugs that block hepatic HMG-CoA reductase, lowering blood LDL cholesterol synthesis.\n2. **Aspirin:** Antiplatelet drug taken at low daily doses to reduce platelet aggregation and blood clot formation.\n3. **Angioplasty and Stents:** A tiny balloon is threaded into narrowed coronary arteries and inflated to open the lumen; an expandable mesh tube (**stent**) is left in place to keep the vessel patent.\n4. **Coronary Artery Bypass Graft (CABG):** A healthy blood vessel (typically from the patient's leg or chest) is grafted to bypass blocked sections of coronary arteries.",
