        "title": "Veins: Structure & Function",
        "body": "### Veins: Low-Pressure Vessels\n\n- **Function:** Transport deoxygenated blood from capillary beds back towards the heart under very low hydrostatic pressure (exception: pulmonary vein carries oxygenated blood from lungs to left atrium).\n- **Structure:**\n  - Relatively thin muscular and elastic wall (because blood pressure is low and smooth).\n  - **Wide lumen:** Minimizes resistance to blood flow.\n  - **Semilunar pocket valves:** Spaced along the length of veins to ensure unidirectional blood flow towards the heart, preventing venous pooling.\n  - Surrounding skeletal muscles contract during bodily movement, compressing veins and driving blood through valves towards the heart.",
