    "section": "9. Transport in Animals",
    "topic": "Circulatory Systems, Heart & Blood Vessels",
    "intro": "Revision notes for **Comparing Blood Vessels** under **Circulatory Systems, Heart & Blood Vessels** (9. Transport in Animals). Cambridge IGCSE Biology (0610/0970).",
    "subheadings": [
      {
        "title": "Comparing Blood Vessels",
        "body": "### Comparison of Arteries, Veins, and Capillaries\n\n| Characteristic | Artery | Vein | Capillary |\n| :--- | :--- | :--- | :--- |\n| **Direction of Flow** | Away from heart | Towards heart | Links arterioles to venules |\n| **Blood Pressure** | High and pulsatile | Low and smooth | Drops from arteriole to venule end |\n| **Oxygenation** | Oxygenated (except pulmonary artery) | Deoxygenated (except pulmonary vein) | Deoxygenates as blood passes tissue |\n| **Lumen Size** | Relatively narrow | Wide | Microscopic (~one RBC diameter) |\n| **Wall Thickness** | Very thick | Thin | Microscopic (one cell layer) |\n| **Muscle & Elastic Fibre** | Abundant (thick tunica media) | Small amount | Absent (endothelium only) |\n| **Valves** | None (except at base of aorta/pulmonary artery) | Semi-lunar valves present | None |",
        "groups": [],
        "examinerTips": [
          "In exam questions providing three vessel cross-sections, identify artery by thick wavy wall, vein by large floppy lumen, and capillary by single cell thickness."
        ],
        "commonMistakes": [
          "Claiming arteries always carry oxygenated blood. The pulmonary artery carries deoxygenated blood to the lungs."
        ],
        "recap": [
          "Construct a table comparing the lumen size, wall thickness, and presence of valves in arteries and veins. [3]"
        ],
        "figure": "![Comparing Blood Vessels](/notes/biology/uq-comparing-blood-vessels.webp)"
      }
    ]
