        "title": "Cardiovascular Health: Summary & Calculations",
        "body": "### Cardiovascular Calculations & Key Points\n\n#### Cardiac Output Formula:\n$$\\text{Cardiac Output } (cm^3/min) = \\text{Heart Rate } (beats/min) \\times \\text{Stroke Volume } (cm^3/beat)$$\n\n- Example: A student has a resting heart rate of 72 bpm and a stroke volume of $70\\text{ cm}^3$. Cardiac output = $72 \\times 70 = 5040\\text{ cm}^3/\\text{min}$ ($~5\\text{ L/min}$).\n- During exercise, elite athletes achieve cardiac outputs exceeding $30\\text{ L/min}$ primarily through dramatic increases in stroke volume developed via ventricular hypertrophic conditioning.",
