        "body": "### Structural Role of Cartilage\n\n- The **trachea** and **bronchi** are supported by C-shaped rings of tough, flexible connective tissue called **cartilage**.\n- **Function:** Cartilage provides structural support, preventing the airway from collapsing inwards when thoracic pressure drops below atmospheric pressure during forceful inhalation.\n- The rings are C-shaped (open at the posterior side bordering the oesophagus) to allow the oesophagus to expand freely when boluses of food are swallowed.",
