        "title": "Structure of Neurons: Sensory, Relay & Motor",
        "body": "### The Three Types of Neurones\n\n1. **Sensory Neurone:**\n   - Transmits electrical impulses from sensory receptors (e.g. retinal photoreceptors, skin thermoreceptors) to the central nervous system (CNS).\n   - Structure: Long dendron conducting towards cell body (located outside CNS in dorsal root ganglion), short axon entering spinal cord.\n2. **Relay Neurone (Interneurone):**\n   - Situated entirely within the grey matter of the spinal cord and brain.\n   - Structure: Highly branched dendrites and multiple short axons connecting sensory to motor neurones.\n3. **Motor Neurone:**\n   - Conducts nerve impulses from the CNS to effector organs (muscles and endocrine/exocrine glands).\n   - Structure: Cell body located inside CNS; long myelinated axon conducting impulses to neuromuscular junctions.\n\n- **Myelin Sheath:** Fatty insulating layer formed by Schwann cells that dramatically speeds up electrical impulse transmission via saltatory conduction.",
