    "number": 104,
    "title": "Synapses & Neurotransmitter Transmission",
    "section": "14. Coordination & Response",
    "topic": "Coordination, Response & Homeostasis",
    "intro": "Revision notes for **Synapses & Neurotransmitter Transmission** under **Coordination, Response & Homeostasis** (14. Coordination & Response). Cambridge IGCSE Biology (0610/0970).",
    "subheadings": [
      {
        "title": "Synapses & Neurotransmitter Transmission",
        "body": "### Synaptic Transmission Mechanism\n\n- A **synapse** is a microscopic junction between two neurones (typically ~20 nm gap called the synaptic cleft).\n\n#### Sequence of Transmission:\n1. An electrical action potential arrives at the pre-synaptic terminal bulb.\n2. Voltage-gated calcium channels open, causing vesicles containing **neurotransmitter** chemical (e.g. acetylcholine) to fuse with the pre-synaptic membrane.\n3. Neurotransmitter is released into the synaptic cleft by **exocytosis**.\n4. Neurotransmitter molecules **diffuse** across the synaptic cleft down their concentration gradient.\n5. Neurotransmitter binds to complementary **receptor proteins** on the post-synaptic cell membrane.\n6. This triggers ion channels to open, generating a new electrical impulse in the post-synaptic neurone.\n7. An enzyme (e.g. acetylcholinesterase) rapidly breaks down the neurotransmitter to prevent continuous, uncontrolled stimulation.\n\n- **Unidirectionality:** Synapses ensure nerve impulses travel in ONE direction only, because vesicles are located only in the pre-synaptic bulb and receptors are present only on the post-synaptic membrane.",
        "groups": [],
        "examinerTips": [
          "Explain why impulses can only travel across a synapse in one direction: neurotransmitter vesicles are only in pre-synaptic bulb, receptors only on post-synaptic membrane."
        ],
        "commonMistakes": [
          "Saying electrical impulses jump across the gap. The electrical impulse stops; chemicals (neurotransmitters) **diffuse** across the gap."
        ],
        "recap": [
          "Explain how an impulse is transmitted across a synapse. [4]",
          "State two reasons why synapses are essential in the nervous system. [2]"
        ],
        "figure": "![Synapses & Neurotransmitter Transmission](/notes/biology/uq-synapses-neurotransmitter-transmission.webp)"
      }
    ]
