        "title": "Planning Controlled Investigations & Variables",
        "body": "### Designing a Valid Scientific Investigation (CORMS)\n\nUse the **CORMS** framework for 6-mark practical planning questions in Paper 4 and Paper 6:\n\n- **C — Change (Independent Variable):** What will you change across a minimum of 5 distinct values (e.g. temperatures: 20°C, 30°C, 40°C, 50°C, 60°C)?\n- **O — Organism:** What biological material will be used? Specify species, age, mass, or surface area to ensure standardized tissue.\n- **R — Repeat:** How many times will each trial be repeated (minimum 3 repeats to calculate a mean average and identify anomalies)?\n- **M1 — Measure (Dependent Variable 1):** What exact quantity will you measure (e.g. volume of gas in $cm^3$)?\n- **M2 — Measure (Dependent Variable 2):** Over what specific time period will measurements be recorded (e.g. recorded every 60 seconds for 10 minutes)?\n- **S — Standardise (Controlled Variables):** Name at least two specific variables kept strictly constant, and state the exact equipment used to control them (e.g. 'pH controlled at 7.0 using buffer solution', 'temperature kept at 37°C using thermostatically controlled water bath').",
