        "title": "Biological Drawings Standards: Outlines & Proportions",
        "body": "### Cambridge Biological Drawing Criteria\n\nBiological specimens (leaves, flowers, insect wings, cell cross-sections) must be drawn according to strict exam specifications:\n\n1. **Outline Quality:** Use a sharp HB pencil to draw **clear, single, continuous lines**. Never use sketchy, feathered, or jagged lines.\n2. **No Shading:** Absolutely NO shading, stippling, or cross-hatching of any kind. Delineate boundaries with clear outlines.\n3. **Scale & Proportion:** The drawing must be large, occupying **more than 50%** of the provided answer space, with relative proportions matching the specimen.\n4. **Labelling Lines:**\n   - Drawn with a ruler and pencil, completely straight and horizontal.\n   - Label lines must end exactly on the structure being identified, without arrowheads.\n   - Never cross label lines over one another.\n5. **Magnification & Scale Bar:** Indicate linear dimensions or magnification calculated accurately.",
